async def main(args):
    # wiki_search 返回多行纯文本（每行一条命中），不是 JSON 数组——FromJson 解析不了。
    # 直接按行切分："(未找到)"类提示 → []；每行去空 → hits 数组
    v = str(args.params.get("raw") or "")
    if "未找到" in v or not v.strip():
        return {"hits": []}
    hits = [ln.strip() for ln in v.splitlines() if ln.strip()]
    return {"hits": hits}

async def main(args):
    p = args.params
    topk, scores = p.get("topk") or [], p.get("scores") or []
    if not topk:
        return {"inject": False, "result": ""}
    # 相关性阈值：top1 分数 < 0.5 判无关（实测相关问题 top1≈0.7+，无关≈0.3-0.4）——
    # 关键词可能命中 wiki 行但语义不相关，靠 embedding 分数做最终裁决
    top1 = scores[0] if scores and isinstance(scores[0], (int, float)) else 0
    if top1 < 0.5:
        return {"inject": False, "result": ""}
    lines = ["📖 相关 wiki（本地检索流水线命中）："]
    for i, t in enumerate(topk):
        s = scores[i] if i < len(scores) else ""
        stxt = f" ({s})" if isinstance(s, (int, float)) and s >= 0.5 else ""
        lines.append(f"{i+1}. {str(t)[:200]}{stxt}")
    return {"inject": True, "result": "\n".join(lines)}
